WITH enriched AS (SELECT e.*, b.channel, b.amount FROM shipments e JOIN orders b ON e.order_id = b.id), scored AS (SELECT id, order_id, carrier, shipped_date, delivered_date, cost, status, channel, amount, AVG(amount) OVER (PARTITION BY status, carrier ORDER BY cost, id ROWS BETWEEN 5 PRECEDING AND CURRENT ROW) amount_avg_5, AVG(cost) OVER (PARTITION BY order_id ORDER BY shipped_date, id ROWS BETWEEN 6 PRECEDING AND CURRENT ROW) cost_avg_6, AVG(cost) OVER (PARTITION BY channel ORDER BY amount, id ROWS BETWEEN 5 PRECEDING AND CURRENT ROW) cost_avg_5, ROW_NUMBER() OVER (PARTITION BY status ORDER BY delivered_date, id) seq_no FROM enriched), with_window AS (SELECT s.*, pr.id AS promo_id, pr.promo_code, pr.discount_pct FROM scored s JOIN promotions pr ON s.channel <=> pr.channel AND s.delivered_date >= pr.starts_on AND s.delivered_date < pr.ends_on + INTERVAL '14' DAY) SELECT s.id, s.order_id, s.carrier, s.shipped_date, s.cost, s.channel, s.amount, s.cost_avg_6, s.promo_id, (SELECT AVG(x.cost) FROM shipments x WHERE x.order_id = s.order_id) AS avg_shipment_cost FROM with_window s ORDER BY avg_shipment_cost DESC;
